    log_id SERIAL PRIMARY KEY,
    ordersmark TEXT,
    mic NUMERIC,
    calculated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Create the log table
CREATE TABLE IF NOT EXISTS market_impact_cost_log (
    log_id SERIAL PRIMARY KEY,
    ordersmark TEXT,
    mic NUMERIC,
    calculated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Create the procedure to recalculate market impact cost for new orders
CREATE OR REPLACE PROCEDURE recalc_market_impact_cost()
LANGUAGE plpgsql
AS $$
DECLARE
    v_mkteffect NUMERIC;
    v_recordvault TEXT;
    v_notionsum NUMERIC;
    v_mic NUMERIC;
BEGIN
    -- Get the current market factor from systemmonitoring (latest record)
    SELECT mkteffect INTO v_mkteffect 
    FROM systemmonitoring 
    ORDER BY systemmonitoringpivot DESC 
    LIMIT 1;

    -- Delete existing MIC logs for new orders to avoid duplicates
    DELETE FROM market_impact_cost_log 
    WHERE ordersmark IN (SELECT recordvault FROM orders WHERE orderflow = 'New');

    -- Calculate MIC for each new order and insert into log table
    FOR v_recordvault, v_notionsum IN 
        SELECT recordvault, notionsum 
        FROM orders 
        WHERE orderflow = 'New'
    LOOP
        -- MIC formula: notional value * market effect factor
        v_mic := v_notionsum * v_mkteffect;

        INSERT INTO market_impact_cost_log (ordersmark, mic, calculated_at)
        VALUES (v_recordvault, v_mic, NOW());
    END LOOP;
END;
$$;

